-- 10 November 2026. Four-model private, fact-scoped factory archive import.
-- Guards every exact canonical name, empty staged state, outstanding alias,
-- inserted row count and public projection. Never modifies live pages/stock.
DO $$
DECLARE matched integer; inserted integer; before_public integer; after_public integer;
BEGIN
 SELECT count(*) INTO before_public FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,model) AS (VALUES (626,'Royal Enfield','Himalayan 450'),
(631,'Royal Enfield','Shotgun 650'),
(970,'Royal Enfield','Bear 650'),
(255,'Triumph','TIGER 1200'))
 SELECT count(*) INTO matched FROM expected e
 JOIN public.motorcycle_catalog_models m ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.model
 WHERE NOT EXISTS (SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s
 WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS (SELECT 1 FROM public.motorcycle_catalog_model_aliases a
 WHERE a.alias_model_id=e.id AND a.review_status<>'approved');
 IF matched<>4 THEN RAISE EXCEPTION 'Stop: expected 4 exact new models, got %',matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.slot,v.title,v.content,'draft','official_model_specific_history:'||v.source_url,NULL
 FROM (VALUES (626,1,'Model introduction','{"summary":"The Himalayan 450 is Royal Enfield’s later-generation adventure motorcycle, using the Sherpa 450 liquid-cooled engine rather than the Himalayan 411 platform.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-himalayan-450-now-available-with-wire-spoked-tubeless-wheels/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-himalayan-450-now-available-with-wire-spoked-tubeless-wheels/'),
(626,7,'Documented model history','{"summary":"Royal Enfield’s September 2024 release states that the all-new Himalayan 450 was launched in 2023.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-himalayan-450-now-available-with-wire-spoked-tubeless-wheels/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-himalayan-450-now-available-with-wire-spoked-tubeless-wheels/'),
(626,12,'Model-year and equipment evidence','{"summary":"Royal Enfield announced wire-spoked tubeless wheels as a new booking option and genuine accessory in September 2024. This equipment must not be retroactively described as standard on every earlier Himalayan 450.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-himalayan-450-now-available-with-wire-spoked-tubeless-wheels/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-himalayan-450-now-available-with-wire-spoked-tubeless-wheels/'),
(631,1,'Model introduction','{"summary":"The Shotgun 650 is Royal Enfield’s custom-inspired roadster on its 648 cc parallel-twin platform, distinct from the Super Meteor 650 cruiser.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/in/en/motorcycles/shotgun-650/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/in/en/motorcycles/shotgun-650/'),
(631,7,'Documented model history','{"summary":"Royal Enfield records bookings opening on 15 January 2024, with dealer arrivals planned for 24 February 2024 and test rides and deliveries beginning in March 2024 for the Indian market.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/in/en/motorcycles/shotgun-650/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/in/en/motorcycles/shotgun-650/'),
(631,12,'Market-specific technical evidence','{"summary":"The manufacturer’s India-market specifications list a 648 cc parallel twin and a 13.8-litre fuel tank. Equipment and legal specification should be checked separately for other regions.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/in/en/motorcycles/shotgun-650/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/in/en/motorcycles/shotgun-650/'),
(970,1,'Model introduction','{"summary":"The Bear 650 is Royal Enfield’s scrambler-styled member of its 650 twin-cylinder family, visually and functionally distinct from the Interceptor 650.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/content/dam/royal-enfield/india/our-world/news-and-media/news/product-launches/eicma-royalenfield/press-release-eicma-2024.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/content/dam/royal-enfield/india/our-world/news-and-media/news/product-launches/eicma-royalenfield/press-release-eicma-2024.pdf'),
(970,7,'Documented model history','{"summary":"Royal Enfield’s official EICMA announcement of 5 November 2024 introduced the Bear 650 as part of its new European show line-up.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/content/dam/royal-enfield/india/our-world/news-and-media/news/product-launches/eicma-royalenfield/press-release-eicma-2024.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/content/dam/royal-enfield/india/our-world/news-and-media/news/product-launches/eicma-royalenfield/press-release-eicma-2024.pdf'),
(970,13,'Model identity and design evidence','{"summary":"The EICMA release presents the Bear 650 alongside the Classic 650 as a separate heritage-inspired motorcycle; its show launch is not proof of identical regional delivery dates.","source_name":"Royal Enfield official manufacturer evidence","source_url":"https://www.royalenfield.com/content/dam/royal-enfield/india/our-world/news-and-media/news/product-launches/eicma-royalenfield/press-release-eicma-2024.pdf","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.royalenfield.com/content/dam/royal-enfield/india/our-world/news-and-media/news/product-launches/eicma-royalenfield/press-release-eicma-2024.pdf'),
(255,1,'Model introduction','{"summary":"Triumph’s Tiger 1200 is a large-capacity adventure touring motorcycle offered in road- and off-road-oriented configurations.","source_name":"Triumph official manufacturer evidence","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-tiger-1200-22-08-02","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-tiger-1200-22-08-02'),
(255,7,'Documented model history','{"summary":"Triumph’s August 2022 engineering discussion details the redesigned Tiger 1200 generation, noting extensive weight reduction relative to its predecessor. This account does not describe every generation of the Tiger 1200.","source_name":"Triumph official manufacturer evidence","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-tiger-1200-22-08-02","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-tiger-1200-22-08-02'),
(255,12,'2022-generation engineering evidence','{"summary":"Triumph’s 2022 factory question-and-answer article describes a T-Plane triple engine, a claimed 150 PS maximum output and 130 Nm peak torque for that generation. Newer releases require separate model-year treatment.","source_name":"Triumph official manufacturer evidence","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-tiger-1200-22-08-02","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original manufacturer summary for research intake; independent source audit, exact market and variant applicability, and editorial signoff required before release."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-tiger-1200-22-08-02')) v(model_id,slot,title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>12 THEN RAISE EXCEPTION 'Stop: expected 12 research sections, got %',inserted; END IF;
 SELECT count(*) INTO after_public FROM public.motorcycle_universal_published_sections_v1;
 IF before_public<>after_public THEN RAISE EXCEPTION 'Stop: public research projection changed'; END IF;
END $$;